// Copilot Recommendations: the findings (problems, opportunities and risks) and the recommendations built on them. Every finding comes from a RULE over the facts: the same facts always give the same
// findings, with numbers as evidence and no text copied from any memory. A recommendation is classified Critical / High / Medium / Low by the finding's severity and says WHY (motivo), what it GETS
// (beneficio), its IMPACT, its RISK and the modules it involves. The texts are fixed templates: nothing here is generated by a model.

import type { Facts } from "./copilot-context";
import type { Finding, FindingKind, InvolvedModule, PlanType, Recommendation, Severity } from "./copilot-types";

export type ActionTemplate = { actionId: string; label: string };
type Level = "high" | "medium" | "low";
type Rule = {
  id: string; kind: FindingKind; area: PlanType; needs: "general" | "finance"; modules: readonly InvolvedModule[];
  title: string; reason: string; benefit: string; impact: { level: Level; score: number }; risk: { level: Level; note: string };
  actions: readonly ActionTemplate[];
  /** the severity (0–100) and the evidence (numbers and ids only), or nothing when the rule does not apply */
  evaluate(facts: Facts): { severity: number; evidence: string[] } | undefined;
};
const pct = (value: number) => `${Math.round(value * 100)} %`;
const cap = (value: number, max: number) => Math.min(max, Math.round(value));

