export const ruleOf = (id: string): Rule | undefined => RULES.find((rule) => rule.id === id);

export const severityOf = (score: number): Severity => (score >= 80 ? "critical" : score >= 60 ? "high" : score >= 35 ? "medium" : "low");
export const SEVERITY_RANK: Readonly<Record<Severity, number>> = { critical: 4, high: 3, medium: 2, low: 1 };

/** The findings over the facts. A rule that needs money is not even evaluated for someone who may not see money. */
export function evaluateFindings(facts: Facts, canFinance: boolean): Finding[] {
  const found: Finding[] = [];
  for (const rule of RULES) {
    if (rule.needs === "finance" && !canFinance) continue;
    const hit = rule.evaluate(facts);
    if (hit) found.push({ id: rule.id, kind: rule.kind, area: rule.area, severity: hit.severity, evidence: hit.evidence, modules: rule.modules, needs: rule.needs });
  }
  return found.sort((a, b) => b.severity - a.severity || a.id.localeCompare(b.id));
}

/** One recommendation per finding, most severe first (ties by id). */
export function recommend(findings: readonly Finding[]): Recommendation[] {
  return findings.flatMap((finding): Recommendation[] => {
    const rule = ruleOf(finding.id);
    if (!rule) return [];
    return [{
      id: `rec:${rule.id}`, findingId: rule.id, kind: rule.kind, severity: severityOf(finding.severity), score: finding.severity, area: rule.area, title: rule.title, reason: rule.reason, benefit: rule.benefit,
      impact: rule.impact, risk: rule.risk, modules: rule.modules, evidence: finding.evidence, needs: rule.needs,
    }];
  }).sort((a, b) => b.score - a.score || a.id.localeCompare(b.id));
}
